// src/pages/MeetingRoom.js

import {
  useLocation,
} from "react-router-dom";

import {
  useState,
  useEffect,
  useRef,
} from "react";

function MeetingRoom() {
  const location = useLocation();

  // ==================================================
  // 모임 정보
  // ==================================================

  const roomTitle =
    location.state?.title ||
    "독서모임";

  const roomMood =
    location.state?.mood ||
    "badge1";


  // ==================================================
  // 방장 여부
  //
  // 현재는 Community에서 넘겨주는 값으로 테스트
  //
  // isHost: true  → 방장
  // isHost: false → 일반 참가자
  //
  // 나중에는 백엔드에서 받아온 값으로 변경
  // ==================================================

  const isHost =
    location.state?.isHost === true;


  // ==================================================
  // 입력값
  // ==================================================

  const [input, setInput] =
    useState("");


  // ==================================================
  // 채팅 메시지
  // ==================================================

  const [messages, setMessages] =
    useState([
      // --------------------------
      // 처음 입장했을 때 AI
      // --------------------------

      {
        user: "AI",
        type: "ai",
        text:
          "모임원들의 독후감과 기록을 먼저 정리했어요 ✨\n\n• 외로움과 연결감\n• 상실 이후의 성장\n• 잔잔하지만 깊은 감정선\n• 현실적인 인간 관계",
      },

      {
        user: "AI",
        type: "ai",
        text:
          "오늘은 가장 기억에 남았던 문장을 함께 이야기해볼게요 🙂",
      },

      // --------------------------
      // 더미 참가자
      // --------------------------

      {
        user: "민지",
        type: "other",
        color: "#FFB6C1",
        text:
          "저는 마지막 장면이 가장 슬펐어요.",
      },

      {
        user: "현우",
        type: "other",
        color: "#87CEEB",
        text:
          "문장이 진짜 고요해서 좋았어요.",
      },

      {
        user: "서연",
        type: "other",
        color: "#C3E88D",
        text:
          "와타나베 감정선이 너무 현실적이었어요.",
      },
    ]);


  // ==================================================
  // 채팅 마지막 위치
  // ==================================================

  const chatEndRef =
    useRef(null);


  // ==================================================
  // 메시지가 추가되면 아래로 이동
  // ==================================================

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({
      behavior: "smooth",
      block: "nearest",
    });
  }, [messages]);


  // ==================================================
  // 일반 메시지 보내기
  // ==================================================

  const sendMessage = () => {

    if (!input.trim()) {
      return;
    }

    const myMessage = {
      user: "나",
      type: "me",
      text: input.trim(),
    };

    setMessages((prev) => [
      ...prev,
      myMessage,
    ]);

    setInput("");

    // --------------------------------
    // 중요
    //
    // 일반 사용자가 메시지를 보내도
    // AI는 자동으로 답하지 않음
    // --------------------------------
  };


  // ==================================================
  // AI 진행자 호출
  //
  // 방장만 이 함수를 호출할 수 있음
  // ==================================================

  const requestAI = () => {

    // 혹시라도 일반 사용자가
    // 함수를 호출하려고 해도 방지

    if (!isHost) {
      return;
    }


    // --------------------------------
    // 현재까지의 대화 내용
    // --------------------------------

    const conversation =
      messages.map((message) => ({
        user: message.user,
        type: message.type,
        text: message.text,
      }));


    // --------------------------------
    // 나중에 백엔드로 보낼 데이터
    // --------------------------------

    const requestData = {
      roomTitle: roomTitle,
      mood: roomMood,
      messages: conversation,
    };


    console.log(
      "AI 진행자 요청 데이터:",
      requestData
    );


    // ==================================================
    // 나중에 백엔드 연결할 부분
    // ==================================================
    //
    // const response = await fetch(
    //   "http://localhost:8080/api/meeting/ai",
    //   {
    //     method: "POST",
    //     headers: {
    //       "Content-Type": "application/json",
    //     },
    //     body: JSON.stringify(requestData),
    //   }
    // );
    //
    // const data = await response.json();
    //
    // const aiReply = {
    //   user: "AI",
    //   type: "ai",
    //   text: data.message,
    // };
    //
    // setMessages((prev) => [
    //   ...prev,
    //   aiReply,
    // ]);
    //
    // ==================================================


    // ==================================================
    // 현재는 백엔드 연결 전이므로 더미 응답
    // ==================================================

    const aiReply = {
      user: "AI",
      type: "ai",
      text:
        "좋은 의견들이 나오고 있네요 🌿\n\n지금까지 이야기한 내용을 보면 인물의 감정과 상실에 대한 이야기가 많이 나온 것 같아요.\n\n여러분은 이 책에서 가장 공감했던 인물의 감정이 무엇이었나요?",
    };


    setMessages((prev) => [
      ...prev,
      aiReply,
    ]);
  };


  // ==================================================
  // 화면
  // ==================================================

  return (
    <div
      style={{
        width: "100%",
        maxWidth: "430px",
        height: "100vh",
        margin: "0 auto",

        display: "flex",
        flexDirection: "column",

        background: "#ffffff",

        boxSizing: "border-box",

        overflow: "hidden",
      }}
    >

      {/* ==================================================
          헤더
      ================================================== */}

      <div className="meeting-header">

        <div>
          <div className="meeting-room-name">
            📚 {roomTitle}
          </div>
        </div>

      </div>


      {/* ==================================================
          채팅 영역
      ================================================== */}

      <div
        className="meeting-chat-area"
        style={{
          flex: 1,
          minHeight: 0,

          overflowY: "auto",
          overflowX: "hidden",

          boxSizing: "border-box",
        }}
      >

        {messages.map(
          (msg, index) => (

            <div
              key={index}
              className={`chat-row ${
                msg.type === "me"
                  ? "right"
                  : "left"
              }`}
            >

              {/* =========================
                  프로필
              ========================= */}

              {msg.type !== "me" && (

                <div
                  className="chat-profile"
                  style={{
                    background:
                      msg.type === "ai"
                        ? "#9bd44e"
                        : msg.color,
                  }}
                >
                  {msg.user[0]}
                </div>

              )}


              {/* =========================
                  이름 + 말풍선
              ========================= */}

              <div className="chat-content">

                {msg.type !== "me" && (

                  <div className="chat-name">
                    {msg.user}
                  </div>

                )}

                <div
                  className={`chat-bubble ${
                    msg.type === "me"
                      ? "user-chat"
                      : msg.type === "ai"
                      ? "ai-chat"
                      : "other-chat"
                  }`}
                >
                  {msg.text}
                </div>

              </div>

            </div>

          )
        )}


        {/* 마지막 메시지 위치 */}

        <div ref={chatEndRef}></div>

      </div>


      {/* ==================================================
          AI 진행자 버튼
          
          ★ 방장일 때만 렌더링
          
          일반 사용자는 이 영역 자체가 없음
      ================================================== */}

      {isHost && (

        <div
          style={{
            width: "100%",

            flexShrink: 0,

            padding:
              "8px 12px",

            boxSizing:
              "border-box",

            background:
              "#ffffff",

            borderTop:
              "1px solid #eeeeee",

            zIndex: 10,
          }}
        >

          <button
            type="button"
            onClick={requestAI}
            style={{
              display: "block",

              width: "100%",

              height: "44px",

              border: "none",

              borderRadius: "14px",

              background:
                "#eef7da",

              color:
                "#6a8c2f",

              fontSize: "14px",

              fontWeight: "700",

              cursor: "pointer",

              boxSizing:
                "border-box",
            }}
          >
            ✨ AI 진행자에게 질문하기
          </button>

        </div>

      )}


      {/* ==================================================
          입력 영역
      ================================================== */}

      <div
        className="meeting-input-wrap"
        style={{
          flexShrink: 0,
        }}
      >

        <input
          value={input}
          onChange={(e) =>
            setInput(e.target.value)
          }
          placeholder="생각을 입력해보세요"
          onKeyDown={(e) => {

            if (e.key === "Enter") {
              sendMessage();
            }

          }}
        />

        <button
          type="button"
          onClick={sendMessage}
        >
          전송
        </button>

      </div>


    </div>
  );
}

export default MeetingRoom;
